struct vector2di
{
    int x;
    int y;
};

class recti
{
public:
    vector2di tl;
    vector2di br;

    void set_left(const int i) { tl.x = i; }
    void set_right(const int i) { br.x = i; }
    void set_top(const int i) { tl.y = i; }
    void set_bottom(const int i) { br.y = i; }
};

struct kellyslater_controller;

class PushMode
{
protected:
    struct PLAYER
    {
        float share;
        int extraShare;
        recti viewport;
        kellyslater_controller *ks;
        int prevScore;
    };

    PLAYER players[2];
    float attackTimer;
    int scoreRequired;

    void CalcViewports(void);
};

extern "C" void adjustCoords(float &x, float &y)
    __asm__("adjustCoords__H1Zf_RX01T0_v");
__asm__(".equ adjustCoords__H1Zf_RX01T0_v, 0x001D6B60");

void PushMode::CalcViewports(void)
{
    float	x, y;

    x = 0.0f;
    y = 0.0f;
    adjustCoords(x, y);
    players[0].viewport.set_left(int(x));
    players[0].viewport.set_top(int(y));
    x = 640.0f*players[0].share - 1.0f;
    y = 480.0f-1.0f;
    adjustCoords(x, y);
    players[0].viewport.set_right(int(x));
    players[0].viewport.set_bottom(int(y));

    x = 640.0f*players[0].share;
    y = 0.0f;
    adjustCoords(x, y);
    players[1].viewport.set_left(int(x));
    players[1].viewport.set_top(int(y));
    x = 640.0f-1.0f;
    y = 480.0f-1.0f;
    adjustCoords(x, y);
    players[1].viewport.set_right(int(x));
    players[1].viewport.set_bottom(int(y));
}
